
#![forbid(unsafe_code)]
#![deny(unsafe_op_in_unsafe_fn)]
#![deny(unused_must_use)]
#![deny(missing_docs)]

//! # ZCIR Legacy IR Compatibility Adapter
//!
//! Canonical path: `src/classical/zcir/lowering/legacy_adapter.rs`
//! Edition: Rust 2021.
//! Minimum intended Rust version: 1.97.
//! Safety: Unsafe Rust is forbidden.
//!
//! ## Purpose
//!
//! Provide an explicit migration and compatibility boundary for the legacy
//! IR generated by `crate::ir_gen`.
//!
//! The legacy IR and canonical ZUIR are different representations. The
//! legacy representation includes target-oriented textual IR generation,
//! legacy type/value models, register names, labels, and instruction variants.
//! Similar-looking fields do not establish equivalent semantics.
//!
//! This module therefore assesses legacy artifacts and identifies known
//! compatibility risks. It deliberately does not construct canonical ZUIR
//! operations or claim that a legacy module is safely convertible.
//!
//! ## Architectural authority
//!
//! This adapter is subordinate to:
//!
//! - `src/ir_gen.rs`: legacy IR representation and generation.
//! - `src/classical/zcir/ir/mod.rs`: ZCIR's canonical IR-facing API.
//! - `src/classical/zcir/ids.rs`: canonical identity integration.
//! - `src/classical/zcir/lowering/to_zuir.rs`: canonical identity adapter.
//! - `src/classical/zcir/lowering/from_zuir.rs`: reverse identity adapter.
//! - `src/zuir/ZUIR-SPEC.md`: canonical IR contract.
//! - `src/zuir/ir/`: canonical IR entities and local invariants.
//! - `src/zuir/verify/`: canonical verification boundaries.
//! - `grammar/DESIGN.md`: grammar authority and design boundaries.
//! - `grammar/Zamani.g4`: source grammar composition.
//! - `grammar/specification/semantic-model.md`: semantic authority.
//! - `grammar/validation/semantic-boundaries.md`: semantic ownership.
//! - `grammar/specification/poco-reaf.md`: portability contract.
//! - `grammar/specification/scalability-model.md`: scalability contract.
//!
//! ## Ownership
//!
//! This file owns:
//!
//! - Legacy compatibility finding codes.
//! - A deterministic, target-independent assessment report.
//! - Inspection of legacy module metadata and instruction categories.
//! - The explicit boundary between legacy artifacts and canonical ZUIR.
//!
//! This file does not own:
//!
//! - A second IR, SSA model, identifier system, or type system.
//! - Source parsing, AST construction, or semantic analysis.
//! - Legacy IR generation or execution.
//! - Canonical ZUIR construction or verification.
//! - Hardware selection, memory allocation, scheduling, or code generation.
//! - A speculative conversion from legacy instructions to ZUIR operations.
//!
//! ## Integration contract
//!
//! 1. Legacy IR enters through `crate::ir_gen::IrModule`.
//! 2. `assess_legacy_module` reports compatibility risks without modifying
//!    the supplied module.
//! 3. Assessment findings are ordered deterministically.
//! 4. Findings are not proof that a particular conversion is impossible;
//!    they identify risks that require explicit review or mapping.
//! 5. An empty findings list is not a substitute for canonical verification.
//! 6. No legacy artifact may be treated as canonical ZUIR merely because
//!    its names or instruction shapes resemble canonical operations.
//! 7. A future conversion must use canonical ZUIR IDs, types, operation
//!    constructors, and verification APIs.
//! 8. Any conversion that cannot preserve source meaning must fail
//!    explicitly rather than silently approximate that meaning.
//!
//! ## Scalability
//!
//! This module defines no fixed maximum for modules, functions, instructions,
//! operands, types, or resources. Report storage grows with the number of
//! findings. Assessment work is proportional to the legacy module's
//! functions and instructions inspected.
//!
//! The assessment does not allocate target resources or recursively traverse
//! arbitrary source-level nesting. It remains subject to ordinary Rust
//! collection, address-space, and allocation constraints.
//!
//! ## Grammar and semantic boundary
//!
//! Grammar defines source syntax; frontend semantic analysis defines
//! resolved meaning. This adapter consumes an already-generated legacy IR
//! artifact and cannot recover information that an upstream transformation
//! has already discarded. In particular, it cannot reverse an earlier
//! machine-width collapse or infer missing effect and provenance metadata.
//!
//! ## Migration rule
//!
//! The legacy IR must remain a compatibility input until a verified
//! replacement pipeline covers the supported instruction set. Retirement
//! requires differential tests, semantic-preservation tests, and successful
//! downstream integration—not merely a successful assessment.

use crate::ir_gen::{IrFunction, IrInstruction, IrModule, IrType};

/// Stable code identifying a legacy compatibility finding.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum LegacyFindingCode {
    /// The legacy representation contains target-oriented IR metadata.
    TargetSpecificMetadata,

    /// The legacy representation uses a textual backend-oriented encoding.
    BackendOrientedRepresentation,

    /// Legacy machine-width semantics may already have been collapsed.
    MachineWidthSemanticsMayBeLost,

    /// Legacy pointer operations require an explicit memory-model mapping.
    PointerOrMemorySemantics,

    /// Legacy control-flow structures require explicit CFG reconstruction.
    ControlFlowRequiresMapping,

    /// Legacy operations require explicit arithmetic semantic mappings.
    ArithmeticSemanticsRequireMapping,

    /// Legacy quantum or Zamani-specific operations require domain mappings.
    DomainOperationRequiresMapping,

    /// Legacy call instructions require explicit call and effect contracts.
    CallSemanticsRequireMapping,

    /// Legacy values or types require explicit representation mappings.
    TypeOrValueMappingRequired,

    /// Conversion has not been proven lossless for this artifact.
    LosslessConversionNotEstablished,
}

/// One compatibility finding for a legacy IR artifact.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct LegacyFinding {
    code: LegacyFindingCode,
    location: String,
    explanation: String,
    action: String,
}

impl LegacyFinding {
    /// Construct a compatibility finding.
    fn new(
        code: LegacyFindingCode,
        location: impl Into<String>,
        explanation: impl Into<String>,
        action: impl Into<String>,
    ) -> Self {
        Self {
            code,
            location: location.into(),
            explanation: explanation.into(),
            action: action.into(),
        }
    }

    /// Return the stable finding code.
    #[must_use]
    pub const fn code(&self) -> LegacyFindingCode {
        self.code
    }

    /// Return the logical location associated with the finding.
    ///
    /// Locations are descriptive paths, not source-map identities.
    #[must_use]
    pub fn location(&self) -> &str {
        &self.location
    }

    /// Return the explanation of the compatibility risk.
    #[must_use]
    pub fn explanation(&self) -> &str {
        &self.explanation
    }

    /// Return the recommended action needed to resolve the finding.
    #[must_use]
    pub fn action(&self) -> &str {
        &self.action
    }
}

/// Result of inspecting a legacy IR module.
///
/// This report does not contain or imply a converted ZUIR module.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct LegacyAssessment {
    module_name: String,
    function_count: usize,
    instruction_count: usize,
    findings: Vec<LegacyFinding>,
}

impl LegacyAssessment {
    /// Return the inspected legacy module's name.
    #[must_use]
    pub fn module_name(&self) -> &str {
        &self.module_name
    }

    /// Return the number of functions inspected.
    #[must_use]
    pub const fn function_count(&self) -> usize {
        self.function_count
    }

    /// Return the number of legacy instructions inspected.
    #[must_use]
    pub const fn instruction_count(&self) -> usize {
        self.instruction_count
    }

    /// Borrow the ordered compatibility findings.
    #[must_use]
    pub fn findings(&self) -> &[LegacyFinding] {
        &self.findings
    }

    /// Return whether the report contains any findings.
    ///
    /// This is a report property only. It is not a canonical IR verification
    /// result and does not authorize conversion or execution.
    #[must_use]
    pub fn has_findings(&self) -> bool {
        !self.findings.is_empty()
    }

    /// Return whether this report is suitable for automatic conversion.
    ///
    /// Automatic conversion is intentionally disabled until a dedicated
    /// converter proves that the complete legacy representation, including
    /// types, values, control flow, effects, and metadata, is preserved.
    #[must_use]
    pub const fn permits_automatic_conversion(&self) -> bool {
        false
    }
}

/// Inspect a legacy IR module for known compatibility risks.
///
/// This function is read-only. It neither mutates the legacy module nor
/// constructs canonical ZUIR entities.
///
/// The output order is deterministic for the same module contents and
/// implementation version.
///
/// # Complexity
///
/// O(F + I + T), where F is the number of functions, I is the number of
/// instructions, and T is the number of recursively visited legacy type
/// descriptors in signatures and selected instruction operands.
///
/// The report consumes memory proportional to its findings. No universal
/// module or instruction ceiling is introduced.
///
/// # Important
///
/// A finding-free report would still not establish semantic equivalence,
/// canonical validity, dialect legality, or target feasibility.
#[must_use]
pub fn assess_legacy_module(module: &IrModule) -> LegacyAssessment {
    let mut findings = Vec::new();
    let mut instruction_count = 0usize;

    findings.push(LegacyFinding::new(
        LegacyFindingCode::BackendOrientedRepresentation,
        "module",
        "The legacy IR is a separate representation with backend-oriented \
         textual emission. It is not a canonical ZUIR artifact.",
        "Define and test an explicit mapping to canonical ZUIR entities. \
         Preserve operation ordering, types, effects, control flow, and \
         values; reject unsupported or ambiguous mappings.",
    ));

    if !module.target_triple.is_empty() || !module.data_layout.is_empty() {
        findings.push(LegacyFinding::new(
            LegacyFindingCode::TargetSpecificMetadata,
            "module.target",
            "The legacy module carries a target triple and data-layout \
             string. These fields may constrain the artifact to a particular \
             target or encode target-specific assumptions.",
            "Separate source-level requirements from target realization. \
             Preserve the original metadata as provenance when appropriate, \
             and resolve target-specific layout only in a target-aware stage.",
        ));
    }

    // The legacy IrType model does not preserve every source-level machine
    // width distinction. Inspection cannot restore distinctions already lost
    // before this adapter receives the module.
    findings.push(LegacyFinding::new(
        LegacyFindingCode::MachineWidthSemanticsMayBeLost,
        "legacy.types",
        "The legacy AST-to-IR mapping can map isize to a fixed-width integer. \
         The resulting type does not identify whether the original source \
         required target-sized integer semantics.",
        "Audit the upstream type-lowering contract. Preserve source-level \
         signedness and width semantics in canonical type metadata before \
         target-specific lowering.",
    ));

    for (function_index, function) in module.functions.iter().enumerate() {
        inspect_function(
            function_index,
            function,
            &mut instruction_count,
            &mut findings,
        );
    }

    // The legacy representation is not yet covered by a proven complete,
    // lossless conversion contract. Keep this finding until the converter and
    // its conformance suite actually establish that contract.
    findings.push(LegacyFinding::new(
        LegacyFindingCode::LosslessConversionNotEstablished,
        "module",
        "A complete, tested conversion from every relevant legacy IR construct \
         to canonical ZUIR has not been established by this adapter.",
        "Implement conversion only against the actual canonical ZUIR API. \
         Add positive, negative, boundary, differential, and round-trip tests. \
         Remove this gate only when supported constructs have proven mappings \
         and unsupported constructs fail explicitly.",
    ));

    LegacyAssessment {
        module_name: module.name.clone(),
        function_count: module.functions.len(),
        instruction_count,
        findings,
    }
}

/// Inspect a legacy function without changing it.
fn inspect_function(
    function_index: usize,
    function: &IrFunction,
    instruction_count: &mut usize,
    findings: &mut Vec<LegacyFinding>,
) {
    let function_path = format!("functions[{function_index}]({})", function.name);

    for (_, ty) in &function.params {
        inspect_type(ty, &function_path, findings);
    }
    inspect_type(&function.return_type, &function_path, findings);

    if function.is_external {
        findings.push(LegacyFinding::new(
            LegacyFindingCode::CallSemanticsRequireMapping,
            format!("{function_path}.linkage"),
            "The legacy function is externally declared. Symbol resolution, \
             calling convention, effects, and ABI requirements are not \
             represented by this adapter.",
            "Map linkage and ABI metadata explicitly, or reject the function \
             when its external contract cannot be preserved.",
        ));
    }

    for (instruction_index, instruction) in function.body.iter().enumerate() {
        *instruction_count = instruction_count.saturating_add(1);

        let path = format!("{function_path}.body[{instruction_index}]");

        match instruction {
            IrInstruction::Alloca(_, ty) => {
                inspect_type(ty, &path, findings);
                push_once_per_code(
                    findings,
                    LegacyFindingCode::PointerOrMemorySemantics,
                    &path,
                    "Stack allocation requires an explicit mapping for storage \
                     lifetime, alignment, ownership, and memory effects.",
                    "Map the allocation to canonical memory and effect \
                     contracts; do not infer physical addresses in ZCIR.",
                );
            }

            IrInstruction::Load(_, pointer)
            | IrInstruction::Store(_, pointer)
            | IrInstruction::GetElementPtr(_, pointer, _) => {
                inspect_type(&pointer.ty(), &path, findings);
                push_once_per_code(
                    findings,
                    LegacyFindingCode::PointerOrMemorySemantics,
                    &path,
                    "The instruction operates on pointer-like values and \
                     requires a defined memory and aliasing model.",
                    "Preserve memory effects, aliasing assumptions, ordering, \
                     and failure behavior in the canonical representation.",
                );
            }

            IrInstruction::BitCast(_, value, target_type)
            | IrInstruction::ZExt(_, value, target_type)
            | IrInstruction::SExt(_, value, target_type)
            | IrInstruction::Trunc(_, value, target_type)
            | IrInstruction::FpExt(_, value, target_type)
            | IrInstruction::FpTrunc(_, value, target_type)
            | IrInstruction::SIToFP(_, value, target_type)
            | IrInstruction::FPToSI(_, value, target_type) => {
                inspect_type(&value.ty(), &path, findings);
                inspect_type(target_type, &path, findings);
                push_once_per_code(
                    findings,
                    LegacyFindingCode::TypeOrValueMappingRequired,
                    &path,
                    "A conversion instruction carries type-specific behavior \
                     that cannot be inferred from its textual spelling alone.",
                    "Specify width, signedness, overflow, rounding, invalid \
                     conversion, and target-independent semantics explicitly.",
                );
            }

            IrInstruction::Label(_)
            | IrInstruction::Jump(_)
            | IrInstruction::CondJump(_, _, _)
            | IrInstruction::Phi(_, _)
            | IrInstruction::Ret(_)
            | IrInstruction::Unreachable => {
                push_once_per_code(
                    findings,
                    LegacyFindingCode::ControlFlowRequiresMapping,
                    &path,
                    "Legacy labels, branches, phi nodes, and terminators need \
                     explicit reconstruction of the canonical control-flow \
                     graph and SSA relationships.",
                    "Map labels to canonical blocks, resolve every successor, \
                     preserve predecessor-sensitive phi semantics, and run \
                     the canonical control-flow and SSA verifiers.",
                );
            }

            IrInstruction::Add(_, _, _)
            | IrInstruction::Sub(_, _, _)
            | IrInstruction::Mul(_, _, _)
            | IrInstruction::Div(_, _, _)
            | IrInstruction::Rem(_, _, _)
            | IrInstruction::Neg(_, _)
            | IrInstruction::And(_, _, _)
            | IrInstruction::Or(_, _, _)
            | IrInstruction::Xor(_, _, _)
            | IrInstruction::Shl(_, _, _)
            | IrInstruction::Shr(_, _, _)
            | IrInstruction::Not(_, _)
            | IrInstruction::Cmp(_, _, _, _) => {
                push_once_per_code(
                    findings,
                    LegacyFindingCode::ArithmeticSemanticsRequireMapping,
                    &path,
                    "Arithmetic and comparison instructions require explicit \
                     integer, floating-point, overflow, shift, division, and \
                     comparison semantics.",
                    "Map each operation through its canonical dialect schema \
                     and test boundary behavior before optimization or lowering.",
                );
            }

            IrInstruction::Call(_, _, _) | IrInstruction::CallIndirect(_, _, _) => {
                push_once_per_code(
                    findings,
                    LegacyFindingCode::CallSemanticsRequireMapping,
                    &path,
                    "Calls require explicit callee identity, argument and result \
                     typing, linkage, and effect contracts.",
                    "Resolve direct and indirect calls using canonical symbols \
                     and preserve calling and effect semantics.",
                );
            }

            IrInstruction::QuantumGate(_, _, _)
            | IrInstruction::NanoOp(_, _, _)
            | IrInstruction::SankofaRecall(_, _)
            | IrInstruction::SankofaRemember(_, _) => {
                push_once_per_code(
                    findings,
                    LegacyFindingCode::DomainOperationRequiresMapping,
                    &path,
                    "The legacy instruction belongs to a domain-specific or \
                     Zamani-specific operation family. Its semantics cannot \
                     be recovered from a name alone.",
                    "Use a registered canonical dialect contract or return an \
                     explicit unsupported-operation diagnostic.",
                );
            }

            IrInstruction::Assign(_, _) | IrInstruction::Comment(_) => {
                // Assignment and comments still require a complete converter
                // contract. They are not independently sufficient to establish
                // whole-function equivalence.
            }
        }
    }
}

/// Inspect a legacy type descriptor for nested target-sensitive structures.
fn inspect_type(
    ty: &IrType,
    location: &str,
    findings: &mut Vec<LegacyFinding>,
) {
    match ty {
        IrType::Ptr(inner) => {
            push_once_per_code(
                findings,
                LegacyFindingCode::PointerOrMemorySemantics,
                location,
                "The legacy pointer type does not by itself specify a \
                 portable memory, ownership, or address-space contract.",
                "Map the pointer through canonical reference, memory, and \
                 address-space semantics. Do not equate a pointer with an \
                 integer or physical address.",
            );
            inspect_type(inner, location, findings);
        }

        IrType::Array(element, _) => {
            inspect_type(element, location, findings);
        }

        IrType::Struct(_, fields) => {
            for (_, field_type) in fields {
                inspect_type(field_type, location, findings);
            }
        }

        IrType::Function(parameters, result) => {
            for parameter in parameters {
                inspect_type(parameter, location, findings);
            }
            inspect_type(result, location, findings);
        }

        IrType::I8
        | IrType::I16
        | IrType::I32
        | IrType::I64
        | IrType::I128
        | IrType::U8
        | IrType::U16
        | IrType::U32
        | IrType::U64
        | IrType::U128
        | IrType::F32
        | IrType::F64
        | IrType::Void
        | IrType::Bool
        | IrType::Quantum
        | IrType::Opaque(_) => {}
    }
}

/// Add a finding only when its code has not already been reported.
///
/// The first occurrence provides a concrete location; subsequent occurrences
/// of the same category do not produce unbounded duplicate messages.
fn push_once_per_code(
    findings: &mut Vec<LegacyFinding>,
    code: LegacyFindingCode,
    location: &str,
    explanation: &str,
    action: &str,
) {
    if findings.iter().any(|finding| finding.code == code) {
        return;
    }

    findings.push(LegacyFinding::new(
        code,
        location,
        explanation,
        action,
    ));
}

#[cfg(test)]
mod tests {
    use super::{
        assess_legacy_module, LegacyFindingCode,
    };
    use crate::ir_gen::IrModule;

    #[test]
    fn assessment_does_not_mutate_the_legacy_module() {
        let module = IrModule::new("legacy_test");
        let original_name = module.name.clone();
        let original_target = module.target_triple.clone();
        let original_layout = module.data_layout.clone();
        let original_function_count = module.functions.len();

        let report = assess_legacy_module(&module);

        assert_eq!(module.name, original_name);
        assert_eq!(module.target_triple, original_target);
        assert_eq!(module.data_layout, original_layout);
        assert_eq!(module.functions.len(), original_function_count);
        assert_eq!(report.module_name(), "legacy_test");
        assert_eq!(report.function_count(), 0);
        assert_eq!(report.instruction_count(), 0);
    }

    #[test]
    fn assessment_reports_target_and_conversion_gates() {
        let module = IrModule::new("targeted_legacy_module");
        let report = assess_legacy_module(&module);

        assert!(report.has_findings());
        assert!(!report.permits_automatic_conversion());

        assert!(report
            .findings()
            .iter()
            .any(|finding| finding.code()
                == LegacyFindingCode::TargetSpecificMetadata));

        assert!(report
            .findings()
            .iter()
            .any(|finding| finding.code()
                == LegacyFindingCode::LosslessConversionNotEstablished));
    }

    #[test]
    fn assessment_is_deterministic_for_unchanged_input() {
        let module = IrModule::new("deterministic_legacy_module");

        let first = assess_legacy_module(&module);
        let second = assess_legacy_module(&module);

        assert_eq!(first, second);
    }

    #[test]
    fn findings_have_actionable_details() {
        let module = IrModule::new("actionable_legacy_module");
        let report = assess_legacy_module(&module);

        assert!(!report.findings().is_empty());

        for finding in report.findings() {
            assert!(!finding.location().is_empty());
            assert!(!finding.explanation().is_empty());
            assert!(!finding.action().is_empty());
        }
    }
}
